+        }
+        int entryIndex = position.getEntry().getIndex();
+        // stopPrice models the initial trailing stop at entry time.
+        int lookback = 1;
+        if (position.getEntry().isBuy()) {
+            Num highestCloseNum = highestClosePrice(entryIndex, lookback);
